         tile_base < n; tile_base += tile_stride) {
        const long long index = tile_base + threadIdx.x;
        if (index < n)
            sum += input[index];
    }

    __shared__ int warp_sums[kWarpsPerBlock];
    const int total = block_sum(sum, warp_sums);
    if (threadIdx.x == 0)
        partials[blockIdx.x] = total;
}

__global__ void reduce_partials(const int *partials, int *out, int count)
{
    int sum = 0;
    for (int i = threadIdx.x; i < count; i += blockDim.x)
        sum += partials[i];

    __shared__ int warp_sums[kWarpsPerBlock];
    const int total = block_sum(sum, warp_sums);
    if (threadIdx.x == 0)
        *out = total;
}

__global__ void reduce_partial_groups(const int *partials, int *group_sums, int count)
{
    const int index = blockIdx.x * blockDim.x + threadIdx.x;
    const int value = index < count ? partials[index] : 0;

    __shared__ int warp_sums[kWarpsPerBlock];
    const int total = block_sum(value, warp_sums);
    if (threadIdx.x == 0)
        group_sums[blockIdx.x] = total;
}
} // namespace

extern "C" void run(const void *x, const void *k, const void *gy, void *out,
                     void *scratch, int n, int h, int l, int ks)
{
    (void)k;
    (void)gy;
    (void)h;
    (void)l;
    (void)ks;

    if (n <= 0) {
        cudaMemsetAsync(out, 0, sizeof(int));
        return;
    }
    if (n == 1) {
        cudaMemcpyAsync(out, x, sizeof(int), cudaMemcpyDeviceToDevice);
        return;
    }

    const int block_count = (n - 1) / kTileItems + 1;
    if (n <= kTileItems) {
        reduce_one<<<1, kBlockSize>>>((const int *)x, (int *)out, n);
        return;
    }

    const int blocks = block_count < kMaxPartials ? block_count : kMaxPartials;
    int *partials = (int *)scratch;
    reduce_tiles<<<blocks, kBlockSize>>>((const int *)x, partials, n);

    if (blocks <= kSingleFinalLimit) {
        reduce_partials<<<1, kBlockSize>>>(partials, (int *)out, blocks);
    } else {
        int *group_sums = partials + kMaxPartials;
        const int groups = (blocks + kBlockSize - 1) / kBlockSize;
        reduce_partial_groups<<<groups, kBlockSize>>>(partials, group_sums, blocks);
        reduce_partials<<<1, kBlockSize>>>(group_sums, (int *)out, groups);
    }
}

