                    void *scratch, int n, int h, int l, int ks)
{
    if (n <= 0) {
        zeroIntOutput<<<1, 1>>>((int *)out);
        return;
    }

    // For large reductions, replace the multi-stage scratch reduction with
    // output initialization followed by a bounded-CTA atomic final reduction.
    if (n >= (1 << 20)) {
        int blocks = n / 2048 + ((n % 2048) != 0);
        if (blocks > 1024)
            blocks = 1024;

        zeroIntOutput<<<1, 1>>>((int *)out);
        gridStrideAtomicReduce<<<blocks, 256>>>((const int *)x, (int *)out, n);
        return;
    }

    // Keep the existing hierarchical path for smaller inputs.
    int count = n;
    int *input = (int *)x;
    bool flip = false;
    while (count > 1) {
        int blocks = (count + 128 - 1) / 128;
        int *dest = flip ? (int *)scratch + n + 32768 : (int *)scratch;
        reduce0<int><<<blocks, 128, 128 * sizeof(int)>>>(input, dest, count);
        input = dest;
        count = blocks;
        flip = !flip;
    }
    cudaMemcpyAsync(out, input, sizeof(int), cudaMemcpyDeviceToDevice);
}

