/*
    Parallel reduction kernels
*/

#ifndef _REDUCE_KERNEL_H_
#define _REDUCE_KERNEL_H_

#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>
#include <stdio.h>

namespace cg = cooperative_groups;

// Utility class used to avoid linker errors with extern
// unsized shared memory arrays with templated type
template <class T> struct SharedMemory
{
    __device__ inline operator T *()
    {
        extern __shared__ int __smem[];
        return (T *)__smem;
    }

    __device__ inline operator const T *() const
    {
        extern __shared__ int __smem[];
        return (T *)__smem;
    }
};

// specialize for double to avoid unaligned shared-memory access errors
template <> struct SharedMemory<double>
{
    __device__ inline operator double *()
    {
        extern __shared__ double __smem_d[];
        return (double *)__smem_d;
    }

    __device__ inline operator const double *() const
    {
        extern __shared__ double __smem_d[];
        return (double *)__smem_d;
    }
};

template <class T> __device__ __forceinline__ T warpReduceSum(unsigned int mask, T mySum)
{
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        mySum += __shfl_down_sync(mask, mySum, offset);
    }
    return mySum;
}

#if __CUDA_ARCH__ >= 800
// Specialize warpReduceFunc for int inputs to use __reduce_add_sync intrinsic
// when on SM 8.0 or higher
template <> __device__ __forceinline__ int warpReduceSum<int>(unsigned int mask, int mySum)
{
    mySum = __reduce_add_sync(mask, mySum);
    return mySum;
}
#endif

/*
    Parallel sum reduction using shared memory
    - takes log(n) steps for n input elements
    - uses n threads
    - only works for power-of-2 arrays
*/

/* This reduction interleaves which threads are active by using the modulo
   operator.  This operator is very expensive on GPUs, and the interleaved
   inactivity means that no whole warps are active, which is also very
   inefficient */
template <class T> __global__ void reduce0(T *g_idata, T *g_odata, unsigned int n)
{
    // Handle to thread block group
    cg::thread_block cta   = cg::this_thread_block();
    T               *sdata = SharedMemory<T>();

    // load shared mem
    unsigned int tid = threadIdx.x;
    unsigned int i   = blockIdx.x * blockDim.x + threadIdx.x;

    sdata[tid] = (i < n) ? g_idata[i] : 0;

    cg::sync(cta);

    // do reduction in shared mem
    for (unsigned int s = 1; s < blockDim.x; s *= 2) {
        // modulo arithmetic is slow!
        if ((tid % (2 * s)) == 0) {
            sdata[tid] += sdata[tid + s];
        }

        cg::sync(cta);
    }

    // write result for this block to global mem
    if (tid == 0)
        g_odata[blockIdx.x] = sdata[0];
}

// Initialize the result in its own kernel so the following reduction can
// safely use atomicAdd without relying on prior output or scratch contents.
__global__ void zeroIntOutput(int *out)
{
    if (blockIdx.x == 0 && threadIdx.x == 0)
        out[0] = 0;
}

// Each CTA accumulates a grid-stride subset, reduces it within the CTA, and
// contributes exactly one 32-bit atomic addition to the result.
__global__ void gridStrideAtomicReduce(const int *input, int *out, int n)
{
    __shared__ int warp_sums[8];

    const unsigned int tid = threadIdx.x;
    const unsigned int lane = tid & (warpSize - 1);
    const unsigned int warp = tid / warpSize;
    const unsigned long long stride =
        (unsigned long long)blockDim.x * (unsigned long long)gridDim.x;
    const unsigned long long limit = (unsigned long long)n;
    unsigned long long index =
        (unsigned long long)blockIdx.x * (unsigned long long)blockDim.x + tid;

    int sum = 0;
    for (; index < limit; index += stride)
        sum += input[index];

    sum = warpReduceSum<int>(__activemask(), sum);
    if (lane == 0)
        warp_sums[warp] = sum;
    __syncthreads();

    // The first warp combines the eight per-warp totals. The launch uses
    // exactly 256 threads, so all eight shared entries have been written.
    if (warp == 0) {
        int block_sum = (lane < 8) ? warp_sums[lane] : 0;
        block_sum = warpReduceSum<int>(__activemask(), block_sum);
        if (lane == 0)
            atomicAdd(out, block_sum);
    }
}

#endif
extern "C" void run(const void *x, const void *k, const void *gy, void *out,
                    void *scratch, int n, int h, int l, int ks)
{
    if (n <= 0) {
        zeroIntOutput<<<1, 1>>>((int *)out);
        return;
    }

    // For large reductions, replace the multi-stage scratch reduction with
    // output initialization followed by a bounded-CTA atomic final reduction.
    if (n >= (1 << 20)) {
        int blocks = n / 2048 + ((n % 2048) != 0);
        if (blocks > 1024)
            blocks = 1024;

        zeroIntOutput<<<1, 1>>>((int *)out);
        gridStrideAtomicReduce<<<blocks, 256>>>((const int *)x, (int *)out, n);
        return;
    }

    // Keep the existing hierarchical path for smaller inputs.
    int count = n;
    int *input = (int *)x;
    bool flip = false;
    while (count > 1) {
        int blocks = (count + 128 - 1) / 128;
        int *dest = flip ? (int *)scratch + n + 32768 : (int *)scratch;
        reduce0<int><<<blocks, 128, 128 * sizeof(int)>>>(input, dest, count);
        input = dest;
        count = blocks;
        flip = !flip;
    }
    cudaMemcpyAsync(out, input, sizeof(int), cudaMemcpyDeviceToDevice);
}

